  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menggunakan data dari soal nomor 2, jika aturan penjadwalan diubah menjadi Shortest Processing Time (SPT), urutan pekerjaan yang benar adalah...','[{"key": "A", "text": "P1, P2, P3, P4"}, {"key": "B", "text": "P4, P2, P1, P3"}, {"key": "C", "text": "P3, P1, P2, P4"}, {"key": "D", "text": "P2, P4, P1, P3"}]'::jsonb,'A','Aturan Shortest Processing Time (SPT) bertujuan untuk meminimalkan waktu tunggu rata-rata dengan mengerjakan pekerjaan yang paling cepat terlebih dahulu. Urutannya berdasarkan waktu pengerjaan dari yang terkecil ke yang terbesar adalah: P3 (1 jam), P1 (2 jam), P2 (4 jam), dan P4 (5 jam).','AKDING',3);
