  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat penggunaan kapasitas desain yang sebenarnya tercapai disebut sebagai...','[{"key": "A", "text": "Kapasitas Cadangan"}, {"key": "B", "text": "Efisiensi"}, {"key": "C", "text": "Utilisasi"}, {"key": "D", "text": "Produktivitas"}]'::jsonb,'A','Utilisasi adalah persentase dari kapasitas desain yang sebenarnya digunakan. Rumusnya adalah (Output Aktual / Kapasitas Desain) x 100%. Metrik ini memberikan gambaran seberapa besar potensi teoritis dari sebuah sistem yang berhasil dimanfaatkan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari metode Linear Programming dalam optimasi distribusi daya adalah...','[{"key": "A", "text": "Meminimalkan jumlah gardu distribusi"}, {"key": "B", "text": "Memaksimalkan kepuasan pelanggan"}, {"key": "C", "text": "Mengalokasikan sumber daya secara optimal untuk meminimalkan biaya atau memaksimalkan output"}, {"key": "D", "text": "Mempercepat waktu pengiriman material"}]'::jsonb,'A','','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam masalah transportasi untuk distribusi material ke beberapa gardu, metode mana yang bertujuan untuk mencari solusi awal yang mendekati optimal dengan mempertimbangkan "biaya penalti"?','[{"key": "A", "text": "Metode Sudut Barat Laut (North-West Corner)"}, {"key": "B", "text": "Metode Biaya Terkecil (Least Cost)"}, {"key": "C", "text": "Metode Aproksimasi Vogel (Vogel''s Approximation Method)"}, {"key": "D", "text": "Metode Stepping Stone"}]'::jsonb,'A','Ini adalah esensi dari Linear Programming (LP). LP adalah teknik matematis untuk menemukan hasil terbaik (misalnya, biaya minimum atau keuntungan maksimum) dalam sebuah model yang persyaratannya direpresentasikan oleh hubungan linear. Dalam konteks PLN, ini bisa berarti mendistribusikan daya dari berbagai pembangkit ke berbagai gardu dengan biaya serendah mungkin.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode yang paling umum digunakan untuk menyelesaikan masalah penugasan (assignment problem), seperti menugaskan tim teknisi ke lokasi proyek yang berbeda, adalah...','[{"key": "A", "text": "Metode Simpleks"}, {"key": "B", "text": "Metode Hungarian"}, {"key": "C", "text": "Metode Transportasi"}, {"key": "D", "text": "Metode Grafis"}]'::jsonb,'A','VAM dianggap lebih unggul dari metode solusi awal lainnya karena tidak hanya melihat biaya terendah, tetapi juga memperhitungkan "biaya penalti" atau opportunity cost jika tidak memilih rute dengan biaya terendah. Ini menghasilkan solusi awal yang lebih mendekati optimal.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam model Linear Programming, komponen yang mendefinisikan tujuan yang ingin dicapai (misalnya, meminimalkan biaya distribusi) disebut...','[{"key": "A", "text": "Variabel Keputusan"}, {"key": "B", "text": "Fungsi Kendala"}, {"key": "C", "text": "Fungsi Tujuan"}, {"key": "D", "text": "Batasan Non-negatif"}]'::jsonb,'A','Metode Hungarian adalah algoritma optimasi kombinasional yang dirancang khusus untuk menyelesaikan masalah penugasan (assignment problem) dalam waktu polinomial, membuatnya jauh lebih efisien daripada menggunakan metode simpleks umum untuk kasus spesifik ini.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari metode transportasi berikut yang paling sederhana untuk diimplementasikan tetapi seringkali menghasilkan solusi awal yang jauh dari optimal?','[{"key": "A", "text": "Metode Aproksimasi Vogel"}, {"key": "B", "text": "Metode Sudut Barat Laut (North-West Corner)"}, {"key": "C", "text": "Metode Biaya Terkecil"}, {"key": "D", "text": "Metode MODI"}]'::jsonb,'A','Fungsi Tujuan (Objective Function) adalah persamaan matematika yang mendefinisikan kuantitas yang ingin dioptimalkan (dimaksimalkan atau diminimalkan). Sebagai contoh: Minimalkan Biaya = 10X1 + 12X2, di mana X1 dan X2 adalah variabel keputusan.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Masalah penugasan (assignment problem) adalah kasus khusus dari masalah transportasi di mana...','[{"key": "A", "text": "Biaya transportasi adalah nol"}, {"key": "B", "text": "Jumlah pasokan dan permintaan masing-masing bernilai 1"}, {"key": "C", "text": "Terdapat lebih banyak sumber daripada tujuan"}, {"key": "D", "text": "Semua rute harus digunakan"}]'::jsonb,'A','Metode ini adalah yang paling sederhana karena memulai alokasi dari sel pojok kiri atas (barat laut) pada tabel transportasi dan melanjutkan baris demi baris, tanpa pernah mempertimbangkan biaya transportasi. Akibatnya, solusi awalnya seringkali sangat tidak efisien.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam metode grafis untuk Linear Programming, area yang memenuhi semua fungsi kendala secara bersamaan disebut...','[{"key": "A", "text": "Titik Optimal"}, {"key": "B", "text": "Garis Iso-profit"}, {"key": "C", "text": "Daerah Feasible (Feasible Region)"}, {"key": "D", "text": "Titik Ekstrem"}]'::jsonb,'A','Masalah penugasan adalah kasus khusus dari masalah transportasi di mana setiap sumber (misalnya, teknisi) memiliki pasokan tepat satu, dan setiap tujuan (misalnya, pekerjaan) memiliki permintaan tepat satu. Ini menyederhanakan masalah menjadi penugasan satu-ke-satu.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk memonitor performa tegangan pada sebuah jaringan listrik dari waktu ke waktu dan mendeteksi adanya variasi yang tidak wajar, alat statistik yang paling tepat digunakan adalah...','[{"key": "A", "text": "Diagram Pareto"}, {"key": "B", "text": "Peta Kendali (Control Chart)"}, {"key": "C", "text": "Diagram Tulang Ikan (Fishbone Diagram)"}, {"key": "D", "text": "Histogram"}]'::jsonb,'A','Dalam metode grafis, setiap fungsi kendala digambarkan sebagai garis. Daerah Feasible adalah area yang dibatasi oleh garis-garis ini, di mana semua kendala terpenuhi secara bersamaan. Solusi optimal dari masalah LP dijamin berada di salah satu titik sudut (vertex) dari daerah ini.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam uji hipotesis untuk menganalisis apakah sebuah unit pembangkit baru memiliki efisiensi yang lebih tinggi dari standar, hipotesis nol (H0) yang benar adalah...','[{"key": "A", "text": "Efisiensi unit baru lebih tinggi dari standar"}, {"key": "B", "text": "Efisiensi unit baru lebih rendah dari standar"}, {"key": "C", "text": "Efisiensi unit baru tidak sama dengan standar"}, {"key": "D", "text": "Efisiensi unit baru sama dengan (tidak berbeda dari) standar"}]'::jsonb,'A','','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah yang BUKAN merupakan karakteristik dari distribusi normal?','[{"key": "A", "text": "Kurva berbentuk lonceng dan simetris"}, {"key": "B", "text": "Mean, median, dan modus berada di titik yang sama"}, {"key": "C", "text": "Kurva miring ke kanan (skewed to the right)"}, {"key": "D", "text": "Total area di bawah kurva adalah 1"}]'::jsonb,'A','Peta Kendali adalah alat utama dari Statistical Process Control (SPC). Ini adalah grafik yang memvisualisasikan data proses dari waktu ke waktu terhadap batas kendali atas (UCL) dan bawah (LCL) untuk mendeteksi apakah variasi dalam proses bersifat wajar (common cause) atau karena faktor yang tidak terduga (special cause).','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang analis menolak hipotesis nol (H0) yang sebenarnya benar. Kesalahan ini disebut...','[{"key": "A", "text": "Kesalahan Tipe I"}, {"key": "B", "text": "Kesalahan Tipe II"}, {"key": "C", "text": "Kesalahan Sampling"}, {"key": "D", "text": "Standar Error"}]'::jsonb,'A','Dalam pengujian hipotesis, Hipotesis Nol (H0) selalu merupakan pernyataan status quo, netralitas, atau "tidak ada efek". Peneliti mencoba mengumpulkan bukti untuk menolak H0 dan mendukung Hipotesis Alternatif (H1), yang dalam kasus ini adalah "efisiensi unit baru lebih tinggi dari standar".','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Peta kendali yang digunakan untuk memonitor proporsi produk cacat atau jumlah keluhan pelanggan dari total observasi adalah...','[{"key": "A", "text": "P-chart"}, {"key": "B", "text": "X-bar chart"}, {"key": "C", "text": "R-chart"}, {"key": "D", "text": "C-chart"}]'::jsonb,'A','Ciri khas utama dari distribusi normal adalah simetris sempurna. Kurva yang miring (skewed) ke kanan atau ke kiri adalah ciri dari distribusi yang tidak normal.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Teorema yang menyatakan bahwa distribusi rata-rata sampel akan mendekati distribusi normal seiring dengan bertambahnya ukuran sampel, terlepas dari bentuk distribusi populasinya, adalah...','[{"key": "A", "text": "Teorema Bayes"}, {"key": "B", "text": "Teorema Batas Sentral (Central Limit Theorem)"}, {"key": "C", "text": "Hukum Bilangan Besar"}, {"key": "D", "text": "Prinsip Pareto"}]'::jsonb,'A','Kesalahan Tipe I (α) terjadi saat kita menolak H0 padahal H0 benar (false positive), contohnya menyimpulkan ada peningkatan efisiensi padahal sebenarnya tidak ada. Sebaliknya, Kesalahan Tipe II (β) terjadi saat kita gagal menolak H0 padahal H0 salah (false negative).','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari metodologi Six Sigma dalam kontrol kualitas adalah...','[{"key": "A", "text": "Mengurangi variasi dan cacat dalam proses hingga mendekati nol"}, {"key": "B", "text": "Menambah jumlah inspeksi pada akhir proses"}, {"key": "C", "text": "Menetapkan standar kualitas minimum"}, {"key": "D", "text": "Hanya fokus pada kecepatan produksi"}]'::jsonb,'A','Peta kendali digunakan untuk data atribut (kualitatif). P-chart secara spesifik memonitor proporsi atau persentase item yang cacat per sampel. Jenis peta lain seperti C-chart digunakan untuk menghitung jumlah cacat per unit, X-bar chart untuk rata-rata proses, dan R-chart untuk rentang proses.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Model Economic Order Quantity (EOQ) digunakan dalam manajemen inventori untuk menentukan jumlah pesanan optimal yang dapat...','[{"key": "A", "text": "Memaksimalkan biaya penyimpanan"}, {"key": "B", "text": "Meminimalkan total biaya persediaan (biaya pesan dan biaya simpan)"}, {"key": "C", "text": "Menghilangkan kebutuhan akan safety stock"}, {"key": "D", "text": "Mempercepat lead time dari pemasok"}]'::jsonb,'A','Teorema ini sangat fundamental dalam statistik karena menyatakan bahwa jika Anda mengambil sampel yang cukup besar (biasanya n > 30) dari populasi mana pun, distribusi dari rata-rata sampel tersebut akan mendekati distribusi normal. Ini memungkinkan kita membuat inferensi tentang populasi bahkan ketika kita tidak mengetahui bentuk distribusinya.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Waktu yang dibutuhkan sejak pesanan material (seperti kabel atau trafo) dilakukan hingga material tersebut diterima di gudang disebut...','[{"key": "A", "text": "Siklus Waktu (Cycle Time)"}, {"key": "B", "text": "Waktu Tunggu (Lead Time)"}, {"key": "C", "text": "Waktu Proses (Processing Time)"}, {"key": "D", "text": "Waktu Pengiriman (Shipping Time)"}]'::jsonb,'A','Six Sigma adalah metodologi yang berfokus pada peningkatan kualitas dengan mengidentifikasi dan menghilangkan penyebab cacat serta meminimalkan variabilitas dalam proses bisnis. Tujuannya adalah mencapai tingkat 3.4 cacat per sejuta peluang (DPMO), yang secara efektif mendekati nol cacat.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama diadakannya persediaan pengaman (safety stock) adalah...','[{"key": "A", "text": "Untuk memanfaatkan diskon pembelian dalam jumlah besar"}, {"key": "B", "text": "Untuk mengurangi biaya pemesanan tahunan"}, {"key": "C", "text": "Untuk melindungi dari ketidakpastian permintaan dan lead time"}, {"key": "D", "text": "Untuk mengisi gudang hingga kapasitas penuh"}]'::jsonb,'A','','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fenomena di mana variabilitas permintaan cenderung meningkat saat bergerak dari hilir (pelanggan) ke hulu (pemasok) dalam rantai pasok disebut...','[{"key": "A", "text": "Efek Forrester"}, {"key": "B", "text": "Efek Pareto"}, {"key": "C", "text": "Efek Cambuk (Bullwhip Effect)"}, {"key": "D", "text": "Efek Jaringan"}]'::jsonb,'A','Model Economic Order Quantity (EOQ) mencari titik keseimbangan optimal antara dua biaya yang berlawanan: Biaya Pemesanan (timbul setiap kali memesan) dan Biaya Penyimpanan (timbul dari menyimpan inventori). EOQ menemukan jumlah pesanan yang meminimalkan total dari kedua biaya tersebut.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi jaringan logistik di mana barang dari berbagai pemasok diterima di sebuah fasilitas, kemudian langsung disortir dan dikirim ke tujuan tanpa disimpan dalam waktu lama disebut...','[{"key": "A", "text": "Direct Shipping"}, {"key": "B", "text": "Warehousing"}, {"key": "C", "text": "Cross-docking"}, {"key": "D", "text": "Hub and Spoke"}]'::jsonb,'A','Lead time adalah istilah standar yang mencakup seluruh durasi dari saat kebutuhan akan suatu barang diidentifikasi dan pesanan dibuat, hingga barang tersebut tiba dan siap untuk digunakan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses merencanakan, mengimplementasikan, dan mengendalikan aliran produk dari titik konsumsi kembali ke titik asal untuk tujuan perbaikan, daur ulang, atau pembuangan yang tepat disebut...','[{"key": "A", "text": "Logistik Maju (Forward Logistics)"}, {"key": "B", "text": "Logistik Terintegrasi"}, {"key": "C", "text": "Logistik Balik (Reverse Logistics)"}, {"key": "D", "text": "Manajemen Inventori"}]'::jsonb,'A','Persediaan Pengaman (Safety Stock) adalah persediaan ekstra yang disimpan sebagai penyangga (buffer) untuk mencegah stockout (kehabisan stok) yang disebabkan oleh permintaan yang lebih tinggi dari perkiraan atau lead time pemasok yang lebih lama dari perkiraan.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ukuran kuantitatif yang digunakan untuk mengukur kinerja suatu organisasi terhadap tujuan utamanya, seperti "waktu rata-rata pemadaman listrik per pelanggan", disebut...','[{"key": "A", "text": "Metrik"}, {"key": "B", "text": "Target"}, {"key": "C", "text": "Key Performance Indicator (KPI)"}, {"key": "D", "text": "Dashboard"}]'::jsonb,'A','Ini adalah fenomena di mana fluktuasi kecil dalam permintaan di tingkat ritel dapat menyebabkan fluktuasi yang semakin besar saat bergerak ke hulu rantai pasok (grosir, distributor, produsen). Hal ini seperti gerakan lecutan cambuk yang semakin besar di ujungnya.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari sebuah dashboard dalam analisis bisnis adalah...','[{"key": "A", "text": "Menyimpan data historis dalam jumlah besar"}, {"key": "B", "text": "Menyajikan visualisasi data dan KPI secara ringkas untuk mempermudah pemantauan dan pengambilan keputusan"}, {"key": "C", "text": "Melakukan analisis statistik yang kompleks"}, {"key": "D", "text": "Menggantikan laporan dalam format spreadsheet"}]'::jsonb,'A','Cross-docking adalah praktik logistik di mana barang yang diterima di pusat distribusi tidak disimpan, melainkan langsung disiapkan untuk pengiriman ke tujuan selanjutnya. Ini meminimalkan biaya penyimpanan dan mempercepat waktu pengiriman.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode peramalan permintaan tenaga listrik yang didasarkan pada opini dan intuisi para ahli di bidang energi disebut...','[{"key": "A", "text": "Metode Kuantitatif"}, {"key": "B", "text": "Metode Rata-rata Bergerak (Moving Average)"}, {"key": "C", "text": "Metode Kualitatif (Delphi Method)"}, {"key": "D", "text": "Metode Regresi Linear"}]'::jsonb,'A','Berbeda dengan logistik tradisional yang mengalirkan barang dari produsen ke konsumen, reverse logistics mengelola aliran balik barang dari konsumen ke produsen untuk tujuan seperti pengembalian produk, perbaikan, daur ulang, atau pembuangan yang ramah lingkungan.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika data permintaan listrik selama 3 bulan terakhir adalah 150 MW, 160 MW, dan 170 MW, maka peramalan untuk bulan berikutnya menggunakan metode simple moving average 3-periode adalah...','[{"key": "A", "text": "150 MW"}, {"key": "B", "text": "160 MW"}, {"key": "C", "text": "165 MW"}, {"key": "D", "text": "170 MW"}]'::jsonb,'A','','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam konteks PLN, KPI yang mengukur durasi rata-rata gangguan atau pemadaman yang dialami setiap pelanggan adalah...','[{"key": "A", "text": "SAIDI (System Average Interruption Duration Index)"}, {"key": "B", "text": "SAIFI (System Average Interruption Frequency Index)"}, {"key": "C", "text": "CAIDI (Customer Average Interruption Duration Index)"}, {"key": "D", "text": "ENS (Energy Not Supplied)"}]'::jsonb,'A','KPI adalah metrik yang paling penting karena secara langsung mengukur seberapa efektif suatu perusahaan dalam mencapai tujuan strategis utamanya. Sebuah metrik bisa saja mengukur sesuatu ("jumlah perbaikan"), tetapi sebuah KPI akan mengukur kinerja terhadap target ("persentase perbaikan yang selesai dalam 24 jam").','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Keunggulan utama dashboard interaktif dibandingkan laporan statis adalah...','[{"key": "A", "text": "Tampilannya lebih menarik secara visual"}, {"key": "B", "text": "Memungkinkan pengguna untuk melakukan drill-down, filter, dan eksplorasi data secara mandiri"}, {"key": "C", "text": "Ukuran filenya lebih kecil"}, {"key": "D", "text": "Proses pembuatannya lebih cepat"}]'::jsonb,'A','Fungsi utama dashboard adalah menyaring informasi kompleks dan data besar menjadi tampilan visual yang mudah dipahami. Ini memungkinkan para pengambil keputusan untuk melihat gambaran besar, tren, dan anomali secara cepat tanpa harus membaca laporan yang panjang.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Titik di mana total pendapatan sebuah proyek sama dengan total biayanya, sehingga tidak ada keuntungan maupun kerugian, disebut...','[{"key": "A", "text": "Titik Pulang Pokok (Break-Even Point)"}, {"key": "B", "text": "Titik Optimal"}, {"key": "C", "text": "Titik Balik (Return Point)"}, {"key": "D", "text": "Titik Efisiensi"}]'::jsonb,'A','Metode peramalan dibagi menjadi dua: Kuantitatif (menggunakan data historis dan model matematis) dan Kualitatif (mengandalkan penilaian subjektif dan intuisi para ahli). Metode Delphi adalah salah satu contoh metode kualitatif di mana pendapat para ahli dikumpulkan secara anonim untuk mencapai konsensus.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam evaluasi kelayakan proyek distribusi, sebuah proyek dianggap layak jika nilai Net Present Value (NPV) yang dihasilkan adalah...','[{"key": "A", "text": "Negatif"}, {"key": "B", "text": "Sama dengan nol"}, {"key": "C", "text": "Positif (lebih besar dari nol)"}, {"key": "D", "text": "Sama dengan tingkat diskonto"}]'::jsonb,'A','Metode simple moving average (rata-rata bergerak sederhana) menghitung rata-rata dari sejumlah data historis terakhir untuk meramalkan periode berikutnya. Perhitungannya adalah (150 + 160 + 170) / 3 = 160 MW.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rumus yang benar untuk menghitung Return on Investment (ROI) adalah...','[{"key": "A", "text": "(Pendapatan / Biaya Investasi) x 100%"}, {"key": "B", "text": "((Keuntungan Bersih - Biaya Investasi) / Biaya Investasi) x 100%"}, {"key": "C", "text": "(Keuntungan Bersih / Biaya Investasi) x 100%"}, {"key": "D", "text": "(Biaya Investasi / Keuntungan Bersih) x 100%"}]'::jsonb,'A','SAIDI adalah KPI umum di industri utilitas listrik yang mengukur total durasi pemadaman untuk pelanggan rata-rata selama periode waktu tertentu. Semakin rendah nilai SAIDI, semakin baik keandalan sistem. SAIFI, di sisi lain, mengukur frekuensi (seberapa sering) pemadaman terjadi.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya pembangunan gardu induk yang nilainya tidak berubah terlepas dari jumlah listrik yang didistribusikan tergolong sebagai...','[{"key": "A", "text": "Biaya Variabel"}, {"key": "B", "text": "Biaya Tetap"}, {"key": "C", "text": "Biaya Semi-variabel"}, {"key": "D", "text": "Biaya Peluang"}]'::jsonb,'A','Inilah kekuatan utama dashboard interaktif. Pengguna tidak hanya pasif menerima informasi, tetapi dapat secara aktif berinteraksi dengan data—misalnya, dengan mengklik grafik untuk melihat detailnya (drill-down) atau memfilter data berdasarkan wilayah—untuk mendapatkan wawasan baru.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode evaluasi investasi yang mengukur berapa lama waktu yang dibutuhkan agar arus kas masuk dari suatu proyek dapat menutupi biaya investasi awalnya adalah...','[{"key": "A", "text": "Net Present Value (NPV)"}, {"key": "B", "text": "Internal Rate of Return (IRR)"}, {"key": "C", "text": "Payback Period"}, {"key": "D", "text": "Profitability Index (PI)"}]'::jsonb,'A','','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang dilakukan untuk melihat bagaimana perubahan pada variabel kunci (seperti biaya bahan bakar atau permintaan listrik) dapat memengaruhi hasil keputusan (seperti NPV proyek) disebut...','[{"key": "A", "text": "Analisis Regresi"}, {"key": "B", "text": "Analisis Sensitivitas"}, {"key": "C", "text": "Analisis Korelasi"}, {"key": "D", "text": "Analisis BEP"}]'::jsonb,'A','BEP adalah level penjualan di mana sebuah proyek tidak menghasilkan laba maupun rugi, yaitu titik di mana total pendapatan sama persis dengan total biaya (biaya tetap + biaya variabel). Analisis BEP sangat penting untuk menentukan margin keamanan sebuah proyek.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat diskonto yang membuat nilai NPV suatu proyek sama dengan nol disebut...','[{"key": "A", "text": "Return on Investment (ROI)"}, {"key": "B", "text": "Weighted Average Cost of Capital (WACC)"}, {"key": "C", "text": "Internal Rate of Return (IRR)"}, {"key": "D", "text": "Hurdle Rate"}]'::jsonb,'A','Net Present Value (NPV) menghitung nilai sekarang dari semua arus kas masa depan sebuah proyek. Jika NPV > 0, proyek diperkirakan akan menghasilkan keuntungan dan meningkatkan nilai perusahaan, sehingga diterima. Jika NPV < 0, proyek diperkirakan akan merugi dan harus ditolak.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi penambahan kapasitas di mana perusahaan menambah kapasitas sebelum adanya peningkatan permintaan disebut...','[{"key": "A", "text": "Strategi Lag"}, {"key": "B", "text": "Strategi Match"}, {"key": "C", "text": "Strategi Lead"}, {"key": "D", "text": "Strategi Adjustment"}]'::jsonb,'A','Strategi Lead adalah pendekatan proaktif di mana kapasitas ditambahkan untuk mengantisipasi pertumbuhan permintaan. Tujuannya adalah untuk memastikan kapasitas selalu mencukupi dan mencegah kehilangan penjualan. Strategi Lag adalah kebalikannya (menambah kapasitas setelah permintaan meningkat), dan strategi Match mencoba mencocokkan penambahan kapasitas dengan peningkatan permintaan secara bertahap.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tim PLN memiliki 4 pekerjaan dengan urutan dan waktu proses sebagai berikut: P1 (3 jam), P2 (6 jam), P3 (4 jam), P4 (2 jam). Jika menggunakan aturan penjadwalan Longest Processing Time (LPT), urutan pengerjaan yang benar adalah...','[{"key": "A", "text": "P2, P3, P1, P4"}, {"key": "B", "text": "P4, P1, P3, P2"}, {"key": "C", "text": "P1, P2, P3, P4"}, {"key": "D", "text": "P2, P1, P4, P3"}]'::jsonb,'A','Aturan Longest Processing Time (LPT) menjadwalkan pekerjaan dengan waktu proses terpanjang terlebih dahulu. Berdasarkan data, urutan waktu proses dari yang terpanjang ke terpendek adalah: P2 (6 jam), P3 (4 jam), P1 (3 jam), dan P4 (2 jam).','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Produktivitas multifaktor dihitung dengan membandingkan output dengan...','[{"key": "A", "text": "Satu input tunggal (misalnya, tenaga kerja)"}, {"key": "B", "text": "Total biaya produksi"}, {"key": "C", "text": "Beberapa input (misalnya, tenaga kerja, material, energi)"}, {"key": "D", "text": "Jumlah unit yang diproduksi"}]'::jsonb,'A','Produktivitas multifaktor memberikan gambaran yang lebih komprehensif dengan membandingkan output total terhadap gabungan beberapa atau semua input yang digunakan dalam produksi. Ini berbeda dengan produktivitas faktor tunggal yang hanya membandingkan output dengan satu jenis input.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam teori antrean, jika pelanggan datang tetapi menolak untuk bergabung dalam antrean karena terlalu panjang, fenomena ini disebut...','[{"key": "A", "text": "Balking"}, {"key": "B", "text": "Reneging"}, {"key": "C", "text": "Jockeying"}, {"key": "D", "text": "Blocking"}]'::jsonb,'A','Balking adalah istilah dalam teori antrean untuk menggambarkan perilaku pelanggan yang memutuskan untuk tidak bergabung dalam antrean sama sekali. Reneging adalah ketika pelanggan sudah berada dalam antrean tetapi memutuskan untuk pergi sebelum dilayani, dan Jockeying adalah ketika pelanggan berpindah dari satu antrean ke antrean lain yang dianggap lebih cepat.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan contoh dari keputusan taktis dalam manajemen operasi?','[{"key": "A", "text": "Membangun pabrik baru"}, {"key": "B", "text": "Menentukan tata letak fasilitas"}, {"key": "C", "text": "Membuat jadwal produksi bulanan"}, {"key": "D", "text": "Meluncurkan lini produk baru"}]'::jsonb,'A','Keputusan taktis memiliki cakupan jangka menengah dan berfokus pada bagaimana sumber daya yang ada digunakan secara efisien. Membuat jadwal produksi adalah contohnya. Membangun pabrik baru atau meluncurkan produk baru adalah keputusan strategis (jangka panjang), sedangkan menentukan tata letak fasilitas adalah keputusan desain yang juga bersifat jangka panjang.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ukuran kinerja yang membandingkan waktu produktif aktual dengan total waktu yang tersedia disebut...','[{"key": "A", "text": "Utilisasi"}, {"key": "B", "text": "Efisiensi"}, {"key": "C", "text": "Kapasitas"}, {"key": "D", "text": "Throughput"}]'::jsonb,'A','Efisiensi secara spesifik mengukur seberapa baik sumber daya (yang dijadwalkan atau tersedia) digunakan secara produktif. Rumusnya adalah (Waktu Produktif Aktual / Total Waktu Tersedia). Utilisasi lebih umum, sering kali membandingkan output aktual dengan kapasitas desain atau efektif.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbaikan berkelanjutan dalam proses produksi yang berfokus pada langkah-langkah kecil dan inkremental dikenal sebagai...','[{"key": "A", "text": "Six Sigma"}, {"key": "B", "text": "Re-engineering"}, {"key": "C", "text": "Kaizen"}, {"key": "D", "text": "Just-In-Time"}]'::jsonb,'A','Kaizen adalah filosofi Jepang yang berfokus pada perbaikan terus-menerus yang melibatkan semua orang, dari manajemen puncak hingga pekerja lini. Perbaikan ini bersifat kecil, bertahap, dan berkelanjutan, berbeda dengan Re-engineering yang bersifat radikal dan drastis.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam tabel simpleks, kondisi optimal tercapai ketika...','[{"key": "A", "text": "Semua nilai di baris Zj-Cj adalah nol"}, {"key": "B", "text": "Semua nilai di baris Zj-Cj untuk variabel non-basis lebih besar atau sama dengan nol (untuk maksimisasi)"}, {"key": "C", "text": "Variabel basis memiliki nilai negatif"}, {"key": "D", "text": "Terdapat nilai negatif di kolom kanan (RHS)"}]'::jsonb,'A','Baris Zj-Cj (atau baris indikator) pada tabel simpleks menunjukkan potensi peningkatan fungsi tujuan jika satu unit variabel non-basis masuk ke dalam solusi. Dalam masalah maksimisasi, jika semua nilai ini sudah positif atau nol, artinya tidak ada lagi variabel non-basis yang dapat meningkatkan nilai fungsi tujuan, sehingga solusi optimal telah tercapai.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Konsep "dualitas" dalam Linear Programming berarti bahwa...','[{"key": "A", "text": "Setiap masalah LP memiliki dua solusi optimal"}, {"key": "B", "text": "Setiap masalah LP (primal) memiliki masalah cermin (dual) yang terkait"}, {"key": "C", "text": "Model dapat dipecah menjadi dua sub-masalah yang lebih kecil"}, {"key": "D", "text": "Terdapat dua fungsi tujuan yang harus dioptimalkan secara bersamaan"}]'::jsonb,'A','Dualitas adalah konsep fundamental di mana setiap masalah LP memiliki masalah terkait yang disebut dual. Solusi dari masalah primal juga memberikan solusi untuk masalah dualnya. Ini sering digunakan untuk analisis ekonomi dan sensitivitas.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam masalah transportasi, kondisi di mana jumlah alokasi kurang dari (jumlah baris + jumlah kolom - 1) disebut...','[{"key": "A", "text": "Solusi tidak seimbang"}, {"key": "B", "text": "Solusi optimal"}, {"key": "C", "text": "Degenerasi"}, {"key": "D", "text": "Looping"}]'::jsonb,'A','Degenerasi terjadi dalam masalah transportasi ketika solusi dasar yang layak memiliki jumlah sel alokasi yang lebih sedikit dari yang dibutuhkan (baris + kolom - 1). Hal ini dapat menyebabkan kesulitan dalam menerapkan beberapa metode solusi seperti Stepping Stone atau MODI.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Model optimasi yang digunakan untuk menemukan jalur terpendek dari satu titik ke titik lain dalam sebuah jaringan adalah...','[{"key": "A", "text": "Model Pohon Rentang Minimum (Minimum Spanning Tree)"}, {"key": "B", "text": "Model Aliran Maksimum (Maximum Flow)"}, {"key": "C", "text": "Algoritma Dijkstra"}, {"key": "D", "text": "Masalah Penugasan"}]'::jsonb,'A','Algoritma Dijkstra adalah algoritma klasik yang dirancang khusus untuk menemukan jalur terpendek antara dua node dalam sebuah graf berbobot (di mana bobotnya non-negatif). Minimum Spanning Tree menghubungkan semua node dengan total panjang minimum, bukan mencari jalur antar dua titik.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Variabel "slack" ditambahkan ke dalam fungsi kendala Linear Programming untuk...','[{"key": "A", "text": "Mengubah pertidaksamaan \"≥\" menjadi persamaan"}, {"key": "B", "text": "Mengubah pertidaksamaan \"≤\" menjadi persamaan"}, {"key": "C", "text": "Menunjukkan sumber daya yang berlebih"}, {"key": "D", "text": "Menjadi variabel dalam fungsi tujuan"}]'::jsonb,'A','Variabel slack (S) mewakili sumber daya yang tidak terpakai atau kapasitas yang tersisa. Variabel ini ditambahkan ke sisi kiri dari kendala "kurang dari atau sama dengan" (≤) untuk mengubahnya menjadi persamaan yang setara (=), yang merupakan format standar yang dibutuhkan oleh metode simpleks.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang digunakan untuk menentukan seberapa besar perubahan koefisien fungsi tujuan atau nilai RHS tanpa mengubah solusi optimal disebut...','[{"key": "A", "text": "Analisis Dualitas"}, {"key": "B", "text": "Analisis Sensitivitas"}, {"key": "C", "text": "Analisis Parametrik"}, {"key": "D", "text": "Analisis Integer"}]'::jsonb,'A','Analisis sensitivitas (atau analisis pasca-optimalitas) adalah studi tentang bagaimana perubahan dalam parameter input model (seperti biaya atau ketersediaan sumber daya) mempengaruhi solusi optimal. Ini sangat penting untuk memahami seberapa kuat (robust) solusi yang ditemukan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam teori permainan, strategi di mana seorang pemain memilih tindakan yang sama terlepas dari apa yang dilakukan oleh pemain lain disebut...','[{"key": "A", "text": "Strategi Campuran"}, {"key": "B", "text": "Strategi Murni"}, {"key": "C", "text": "Strategi Dominan"}, {"key": "D", "text": "Keseimbangan Nash"}]'::jsonb,'A','Sebuah strategi disebut dominan jika strategi tersebut memberikan hasil terbaik bagi seorang pemain, tidak peduli apa pun strategi yang dipilih oleh pemain lawan. Jika seorang pemain memiliki strategi dominan, mereka akan selalu memilihnya.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ukuran yang menunjukkan seberapa baik suatu proses dapat memenuhi spesifikasi yang ditetapkan oleh pelanggan adalah...','[{"key": "A", "text": "Batas Kendali Proses"}, {"key": "B", "text": "Kapabilitas Proses (Cp & Cpk)"}, {"key": "C", "text": "Rentang Proses (R-value)"}, {"key": "D", "text": "Standar Deviasi"}]'::jsonb,'A','Kapabilitas Proses adalah ukuran statistik yang menilai kemampuan suatu proses untuk menghasilkan output yang sesuai dengan batas spesifikasi yang ditentukan. Cp mengukur potensi kapabilitas, sementara Cpk mengukur kapabilitas aktual dengan memperhitungkan pemusatan proses.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Diagram yang digunakan untuk mengidentifikasi dan mengorganisir kemungkinan penyebab dari suatu masalah atau efek tertentu adalah...','[{"key": "A", "text": "Diagram Pareto"}, {"key": "B", "text": "Peta Kendali"}, {"key": "C", "text": "Diagram Tulang Ikan (Ishikawa Diagram)"}, {"key": "D", "text": "Scatter Plot"}]'::jsonb,'A','Diagram Tulang Ikan, juga dikenal sebagai diagram sebab-akibat, adalah alat visualisasi yang membantu tim melakukan brainstorming untuk mengidentifikasi semua kemungkinan akar penyebab dari suatu masalah (efek) dengan mengkategorikannya ke dalam kelompok-kelompok utama (misalnya, Manusia, Mesin, Metode, Material).','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Distribusi probabilitas yang paling tepat untuk memodelkan jumlah kejadian (misalnya, jumlah gangguan jaringan) dalam interval waktu atau ruang tertentu adalah...','[{"key": "A", "text": "Distribusi Normal"}, {"key": "B", "text": "Distribusi Binomial"}, {"key": "C", "text": "Distribusi Poisson"}, {"key": "D", "text": "Distribusi Eksponensial"}]'::jsonb,'A','Distribusi Poisson sangat berguna untuk memodelkan jumlah kemunculan suatu peristiwa dalam interval tertentu (waktu, area, volume) ketika peristiwa tersebut terjadi secara acak dan independen dengan laju rata-rata yang konstan.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pengambilan sampel di mana setiap anggota populasi memiliki kesempatan yang sama untuk dipilih disebut...','[{"key": "A", "text": "Pengambilan Sampel Stratifikasi (Stratified Sampling)"}, {"key": "B", "text": "Pengambilan Sampel Acak Sederhana (Simple Random Sampling)"}, {"key": "C", "text": "Pengambilan Sampel Klaster (Cluster Sampling)"}, {"key": "D", "text": "Pengambilan Sampel Sistematik"}]'::jsonb,'A','Ini adalah metode dasar pengambilan sampel probabilitas di mana setiap individu atau item dalam populasi memiliki peluang yang sama persis untuk terpilih. Metode ini memastikan sampel yang tidak bias, meskipun mungkin tidak selalu yang paling efisien.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika nilai Cpk suatu proses kurang dari 1, hal ini mengindikasikan bahwa...','[{"key": "A", "text": "Proses tersebut sangat kapabel"}, {"key": "B", "text": "Proses tersebut tidak mampu memenuhi spesifikasi"}, {"key": "C", "text": "Rata-rata proses tepat berada di tengah batas spesifikasi"}, {"key": "D", "text": "Variasi proses sangat kecil"}]'::jsonb,'A','Nilai Cpk 1.0 menunjukkan bahwa proses tersebut "nyaris" tidak mampu memenuhi spesifikasi. Nilai Cpk di bawah 1.0 secara definitif menunjukkan bahwa proses tersebut menghasilkan produk atau layanan yang berada di luar batas spesifikasi yang dapat diterima.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam peta kendali X-bar dan R, R-chart harus dianalisis terlebih dahulu karena...','[{"key": "A", "text": "R-chart lebih mudah dihitung"}, {"key": "B", "text": "Batas kendali X-bar chart bergantung pada nilai R-bar (rata-rata rentang)"}, {"key": "C", "text": "Variasi proses lebih penting daripada rata-rata proses"}, {"key": "D", "text": "R-chart menunjukkan titik-titik di luar spesifikasi"}]'::jsonb,'A','Variabilitas proses (diukur oleh R-chart) harus stabil dan terkendali terlebih dahulu sebelum kita dapat mengevaluasi rata-rata proses (X-bar chart). Rumus untuk batas kendali X-bar chart menggunakan nilai R-bar, sehingga R-chart harus dianalisis terlebih dahulu untuk memastikan nilai R-bar valid.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kesalahan menyimpulkan bahwa tidak ada perbedaan atau efek ketika sebenarnya ada (gagal menolak H0 yang salah) disebut...','[{"key": "A", "text": "Kesalahan Tipe I"}, {"key": "B", "text": "Kesalahan Tipe II"}, {"key": "C", "text": "Tingkat Signifikansi (α)"}, {"key": "D", "text": "Power of the test"}]'::jsonb,'A','Kesalahan Tipe II (β) adalah "false negative", yaitu kegagalan mendeteksi efek atau perbedaan yang sebenarnya ada. Ini terjadi ketika peneliti gagal menolak hipotesis nol (H0) yang sebenarnya salah.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem inventori di mana pemesanan dilakukan pada interval waktu yang tetap, tetapi jumlah pesanannya bervariasi, disebut...','[{"key": "A", "text": "Model Economic Order Quantity (EOQ)"}, {"key": "B", "text": "Model Fixed-Period (P-Model)"}, {"key": "C", "text": "Model Reorder Point (Q-Model)"}, {"key": "D", "text": "Sistem ABC"}]'::jsonb,'A','Dalam model P (periode tetap), level inventori hanya diperiksa pada interval waktu tertentu (misalnya, setiap hari Senin). Pesanan kemudian dilakukan untuk mengembalikan level inventori ke tingkat maksimum yang diinginkan. Ini berbeda dengan model Q (kuantitas tetap) di mana pesanan dilakukan setiap kali stok mencapai titik pemesanan ulang (reorder point).','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi rantai pasok yang berfokus pada kecepatan dan fleksibilitas untuk merespons perubahan permintaan yang tidak terduga disebut...','[{"key": "A", "text": "Rantai Pasok Ramping (Lean Supply Chain)"}, {"key": "B", "text": "Rantai Pasok Efisien"}, {"key": "C", "text": "Rantai Pasok Tangkas (Agile Supply Chain)"}, {"key": "D", "text": "Rantai Pasok Risk-hedging"}]'::jsonb,'A','Agilitas dalam rantai pasok adalah tentang merespons dengan cepat terhadap perubahan pasar yang tidak dapat diprediksi. Ini memprioritaskan fleksibilitas dan kecepatan di atas biaya rendah. Sebaliknya, rantai pasok ramping (lean) berfokus pada efisiensi dan eliminasi pemborosan dalam lingkungan permintaan yang stabil.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemilihan lokasi pusat distribusi untuk meminimalkan total biaya transportasi ke berbagai gardu adalah contoh dari keputusan...','[{"key": "A", "text": "Desain Jaringan Logistik"}, {"key": "B", "text": "Manajemen Transportasi"}, {"key": "C", "text": "Manajemen Inventori"}, {"key": "D", "text": "Pengadaan"}]'::jsonb,'A','Keputusan ini adalah bagian fundamental dari desain jaringan logistik, yang melibatkan penentuan jumlah, lokasi, dan kapasitas fasilitas seperti gudang atau pusat distribusi untuk melayani pasar secara efisien.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penggunaan teknologi seperti RFID (Radio Frequency Identification) dalam logistik bertujuan untuk...','[{"key": "A", "text": "Mengurangi biaya tenaga kerja"}, {"key": "B", "text": "Meningkatkan visibilitas dan pelacakan barang secara real-time"}, {"key": "C", "text": "Mempercepat proses produksi"}, {"key": "D", "text": "Menggantikan penggunaan barcode"}]'::jsonb,'A','RFID memungkinkan identifikasi dan pelacakan otomatis barang tanpa perlu kontak fisik atau pandangan langsung (seperti barcode). Ini memberikan data real-time tentang lokasi dan status barang di seluruh rantai pasok, sehingga secara dramatis meningkatkan visibilitas.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kolaborasi antara PLN (sebagai pembeli) dengan pemasok utama untuk bersama-sama merencanakan peramalan dan pemenuhan inventori disebut...','[{"key": "A", "text": "Vendor-Managed Inventory (VMI)"}, {"key": "B", "text": "Collaborative Planning, Forecasting, and Replenishment (CPFR)"}, {"key": "C", "text": "Outsourcing"}, {"key": "D", "text": "Supplier Consolidation"}]'::jsonb,'A','CPFR adalah inisiatif bisnis di mana mitra dagang dalam rantai pasok berkolaborasi secara ekstensif untuk mengembangkan rencana bersama terkait peramalan permintaan dan jadwal pemenuhan. VMI lebih spesifik, di mana pemasok bertanggung jawab penuh atas inventori di lokasi pelanggan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metrik yang mengukur persentase pesanan yang dapat dipenuhi secara lengkap dan tepat waktu dari stok yang tersedia disebut...','[{"key": "A", "text": "Tingkat Layanan (Service Level) / Fill Rate"}, {"key": "B", "text": "Waktu Siklus Pesanan (Order Cycle Time)"}, {"key": "C", "text": "Akurasi Inventori"}, {"key": "D", "text": "Tingkat Perputaran Persediaan"}]'::jsonb,'A','Fill rate adalah KPI logistik kunci yang mengukur kemampuan perusahaan untuk memenuhi permintaan pelanggan dari stok yang ada. Tingkat layanan yang tinggi adalah tujuan utama dari manajemen inventori.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses mengekstrak data dari berbagai sumber, mengubahnya ke dalam format yang sesuai, dan memuatnya ke dalam data warehouse disebut...','[{"key": "A", "text": "Data Mining"}, {"key": "B", "text": "OLAP (Online Analytical Processing)"}, {"key": "C", "text": "ETL (Extract, Transform, Load)"}, {"key": "D", "text": "Business Reporting"}]'::jsonb,'A','ETL adalah proses inti dalam integrasi data. Extract berarti mengambil data dari sistem sumber. Transform berarti membersihkan, memformat, dan mengubah data tersebut. Load berarti memasukkan data yang sudah ditransformasi ke dalam sistem target seperti data warehouse.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode peramalan yang memberikan bobot yang berbeda pada data historis, di mana data yang lebih baru diberi bobot lebih tinggi, adalah...','[{"key": "A", "text": "Rata-rata Bergerak Sederhana"}, {"key": "B", "text": "Regresi Linear"}, {"key": "C", "text": "Peramalan Naif"}, {"key": "D", "text": "Penghalusan Eksponensial (Exponential Smoothing)"}]'::jsonb,'A','Metode ini adalah jenis rata-rata bergerak terbobot di mana bobot untuk data historis menurun secara eksponensial seiring dengan semakin lamanya data tersebut. Ini membuatnya sangat responsif terhadap tren terbaru dalam data.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Grafik yang paling efektif untuk menunjukkan hubungan atau korelasi antara dua variabel numerik (misalnya, suhu dan konsumsi listrik) adalah...','[{"key": "A", "text": "Diagram Batang (Bar Chart)"}, {"key": "B", "text": "Diagram Lingkaran (Pie Chart)"}, {"key": "C", "text": "Diagram Pencar (Scatter Plot)"}, {"key": "D", "text": "Histogram"}]'::jsonb,'A','Diagram pencar secara visual menampilkan nilai dari dua variabel numerik sebagai kumpulan titik. Pola dari titik-titik ini (misalnya, membentuk garis lurus naik) dapat secara efektif menunjukkan ada atau tidaknya hubungan (korelasi) antara kedua variabel tersebut.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam BI, kemampuan untuk melihat data dari level ringkasan yang tinggi hingga ke detail transaksional disebut...','[{"key": "A", "text": "Slicing and Dicing"}, {"key": "B", "text": "Drill-down"}, {"key": "C", "text": "Pivoting"}, {"key": "D", "text": "Filtering"}]'::jsonb,'A','Drill-down adalah fitur umum dalam alat BI yang memungkinkan pengguna untuk menavigasi dari tampilan data yang diringkas (misalnya, total penjualan per negara) ke tingkat data yang lebih detail (misalnya, penjualan per kota, lalu per toko).','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'KPI yang bersifat leading (memprediksi) adalah...','[{"key": "A", "text": "Ukuran yang menunjukkan hasil kinerja masa lalu"}, {"key": "B", "text": "Ukuran yang dapat memprediksi kinerja di masa depan"}, {"key": "C", "text": "Ukuran yang sulit dihitung"}, {"key": "D", "text": "Ukuran yang berfokus pada laba"}]'::jsonb,'A','KPI leading (memprediksi) mengukur aktivitas atau input yang diharapkan dapat "mendorong" hasil di masa depan. Contohnya adalah "jumlah prospek penjualan baru" yang diharapkan dapat memprediksi "pendapatan penjualan di kuartal berikutnya" (yang merupakan KPI lagging).','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Apa perbedaan utama antara data lake dan data warehouse?','[{"key": "A", "text": "Data lake menyimpan data terstruktur, sedangkan data warehouse menyimpan data tidak terstruktur"}, {"key": "B", "text": "Data lake menyimpan data dalam format mentah, sedangkan data warehouse menyimpan data yang telah diproses dan terstruktur"}, {"key": "C", "text": "Data lake lebih kecil ukurannya"}, {"key": "D", "text": "Data lake hanya untuk data real-time"}]'::jsonb,'A','Ini adalah perbedaan fundamental. Data warehouse memerlukan skema yang terdefinisi dengan baik dan hanya menyimpan data yang relevan dan telah diolah. Sebaliknya, data lake adalah repositori besar yang menyimpan semua jenis data (terstruktur, semi-terstruktur, tidak terstruktur) dalam format aslinya tanpa pra-pemrosesan.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Keuntungan yang hilang karena tidak memilih alternatif terbaik berikutnya saat mengambil keputusan disebut...','[{"key": "A", "text": "Biaya Hangus (Sunk Cost)"}, {"key": "B", "text": "Biaya Peluang (Opportunity Cost)"}, {"key": "C", "text": "Biaya Tetap"}, {"key": "D", "text": "Biaya Marginal"}]'::jsonb,'A','Biaya peluang adalah konsep ekonomi yang sangat penting dalam pengambilan keputusan. Ini mewakili nilai dari alternatif terbaik yang harus dikorbankan ketika memilih suatu tindakan.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya yang telah terjadi di masa lalu dan tidak dapat diubah oleh keputusan apa pun di masa depan disebut...','[{"key": "A", "text": "Biaya Relevan"}, {"key": "B", "text": "Biaya Diferensial"}, {"key": "C", "text": "Biaya Hangus (Sunk Cost)"}, {"key": "D", "text": "Biaya Peluang"}]'::jsonb,'A','Biaya hangus tidak relevan untuk pengambilan keputusan di masa depan karena biaya tersebut sudah dikeluarkan dan tidak dapat dipulihkan kembali, apa pun keputusan yang diambil. Mengikutsertakan biaya hangus dalam analisis adalah kesalahan umum yang disebut sunk cost fallacy.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alat pengambilan keputusan yang menggunakan representasi grafis berbentuk pohon untuk memetakan kemungkinan hasil, biaya, dan probabilitas adalah...','[{"key": "A", "text": "Analisis Monte Carlo"}, {"key": "B", "text": "Pohon Keputusan (Decision Tree)"}, {"key": "C", "text": "Analisis Regresi"}, {"key": "D", "text": "Diagram Pareto"}]'::jsonb,'A','Pohon keputusan secara visual menstrukturkan masalah keputusan yang kompleks, di mana ada urutan keputusan dan peristiwa ketidakpastian. Ini membantu dalam menghitung nilai yang diharapkan (expected value) dari setiap cabang keputusan untuk memilih jalur yang paling optimal.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam analisis biaya, degree of operating leverage (DOL) mengukur...','[{"key": "A", "text": "Seberapa besar utang yang digunakan perusahaan"}, {"key": "B", "text": "Seberapa sensitif laba operasi terhadap perubahan penjualan"}, {"key": "C", "text": "Efisiensi penggunaan aset"}, {"key": "D", "text": "Tingkat pengembalian investasi"}]'::jsonb,'A','DOL yang tinggi berarti bahwa sebagian besar biaya perusahaan adalah biaya tetap. Hal ini menyebabkan perubahan kecil dalam volume penjualan akan menghasilkan perubahan yang jauh lebih besar pada laba operasi (EBIT). Ini menunjukkan tingkat risiko operasional perusahaan.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat membandingkan dua proyek dengan umur ekonomis yang berbeda, metode yang paling tepat untuk digunakan adalah...','[{"key": "A", "text": "Memilih proyek dengan NPV lebih tinggi"}, {"key": "B", "text": "Memilih proyek dengan IRR lebih tinggi"}, {"key": "C", "text": "Menggunakan metode Equivalent Annual Annuity (EAA)"}, {"key": "D", "text": "Menggunakan metode Payback Period"}]'::jsonb,'A','Metode EAA mengubah nilai NPV dari setiap proyek menjadi serangkaian pembayaran tahunan yang setara selama umur proyek tersebut. Dengan membandingkan anuitas tahunan ini, kita dapat membuat perbandingan yang adil antara proyek-proyek dengan umur yang berbeda.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Keputusan untuk membuat komponen sendiri atau membelinya dari pemasok eksternal dikenal sebagai...','[{"key": "A", "text": "Keputusan Outsourcing"}, {"key": "B", "text": "Keputusan Make-or-Buy"}, {"key": "C", "text": "Keputusan Investasi Modal"}, {"key": "D", "text": "Keputusan Penentuan Harga"}]'::jsonb,'A','Ini adalah keputusan klasik dalam manajemen operasi di mana perusahaan harus menganalisis biaya relevan dari memproduksi suatu item secara internal versus membelinya dari pemasok eksternal untuk menentukan pilihan yang paling hemat biaya.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang merupakan contoh dari biaya relevan dalam pengambilan keputusan jangka pendek?','[{"key": "A", "text": "Biaya penyusutan gedung"}, {"key": "B", "text": "Gaji manajer pabrik"}, {"key": "C", "text": "Biaya material tambahan untuk pesanan khusus"}, {"key": "D", "text": "Biaya riset dan pengembangan yang sudah dikeluarkan"}]'::jsonb,'A','Biaya relevan adalah biaya masa depan yang berbeda di antara alternatif keputusan. Biaya material tambahan hanya akan terjadi jika pesanan khusus diterima, sehingga relevan. Biaya penyusutan dan gaji manajer adalah biaya tetap yang tidak berubah, sementara biaya R&D adalah biaya hangus.','AKDING',40);
